"""Lazy loader for the bundled reference data (generated by tools/build_data.py)."""
from __future__ import annotations

import functools
import json
from pathlib import Path

DATA_DIR = Path(__file__).resolve().parent.parent / "data"


@functools.lru_cache(maxsize=None)
def load(name: str):
    with open(DATA_DIR / f"{name}.json", encoding="utf-8") as fh:
        return json.load(fh)


@functools.lru_cache(maxsize=None)
def vehicle_ids() -> frozenset[int]:
    return frozenset(v["id"] for v in load("vehicles"))


@functools.lru_cache(maxsize=None)
def skin_ids() -> frozenset[int]:
    return frozenset(s["id"] for s in load("skins"))


@functools.lru_cache(maxsize=None)
def givable_weapon_ids() -> frozenset[int]:
    return frozenset(w["id"] for w in load("weapons") if w.get("givable"))


@functools.lru_cache(maxsize=None)
def weapon_constants() -> dict[str, int]:
    return {w["constant"]: w["id"] for w in load("weapons") if w.get("constant")}


@functools.lru_cache(maxsize=None)
def natives_by_name() -> dict[str, list[dict]]:
    out: dict[str, list[dict]] = {}
    for n in load("natives") + load("callbacks"):
        out.setdefault(n["name"].lower(), []).append(n)
    return out


@functools.lru_cache(maxsize=None)
def animation_index() -> dict[tuple[str, str], dict]:
    return {(a["library"].upper(), a["name"].upper()): a for a in load("animations")}


@functools.lru_cache(maxsize=None)
def animation_libraries() -> frozenset[str]:
    return frozenset(a["library"].upper() for a in load("animations"))
